"""Anonymized, production-shaped fixture data, one JSON file per feature.

The files are generated by ``scripts/scrub_prod_dump.py`` from a production dump:
a small, connected slice of real rows with every Discord id, name, racetime id,
token, VOD link and free-text note replaced by a consistent fake. Never edit them
by hand and never commit un-scrubbed data here; regenerate instead (see README.md).

``users.json`` holds the fake users and Discord world every feature refers to.
Each other file is one feature: deleting a feature's JSON file removes it from the
tests and the dev server, nothing else needs to change.

Load them into an initialised Tortoise database::

    from testdata import load
    await load()                      # every feature
    await load("asynctournament")     # users + one feature
"""
import datetime
import json
import pathlib
from functools import cache

from tortoise import fields

HERE = pathlib.Path(__file__).resolve().parent
USERS = "users"


def features() -> list:
    """The feature files present, without users."""
    return sorted(p.stem for p in HERE.glob("*.json") if p.stem != USERS)


@cache
def read(name: str) -> dict:
    """The parsed JSON of one file (``users`` or a feature name)."""
    return json.loads((HERE / f"{name}.json").read_text(encoding="utf-8"))


def rows(name: str, model: str) -> list:
    """The rows for one model in one file, as dicts (empty when absent)."""
    for model_name, model_rows in read(name)["tables"]:
        if model_name == model:
            return model_rows
    return []


def world() -> dict:
    """The fake Discord guilds and members the fixture rows refer to."""
    return read(USERS)["world"]


def _convert(model, row: dict) -> dict:
    out = {}
    fields_map = model._meta.fields_map
    for key, value in row.items():
        field = fields_map.get(key)
        if field is None and key.endswith("_id"):
            field = fields_map.get(key[:-3])
        if isinstance(field, fields.DatetimeField) and isinstance(value, str):
            value = datetime.datetime.fromisoformat(value).replace(tzinfo=datetime.timezone.utc)
        out[key] = value
    return out


async def load(*names: str) -> dict:
    """Insert ``users`` and the named features (all of them by default).

    Returns {model name: row count}. Expects the tables to be empty of these ids;
    the fixture ids start at 1001 so they don't collide with hand-made rows.
    """
    from alttprbot import models

    wanted = [USERS] + [n for n in (names or features()) if n != USERS]
    counts = {}
    for name in wanted:
        for model_name, model_rows in read(name)["tables"]:
            model = getattr(models, model_name)
            objects = [model(**_convert(model, r)) for r in model_rows]
            if objects:
                await model.bulk_create(objects, batch_size=500)
            counts[model_name] = counts.get(model_name, 0) + len(objects)
    return counts
